"""Read saved P3 results and build a compact public, data-only projection."""
import collections,datetime,hashlib,json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
OUT=ROOT/'delivery';RUN=ROOT/'results/ff_bf_2024_data_batch_20261004_01'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def timestamp_ns(s):
 base,frac=s.removesuffix('Z').split('.')
 return int(datetime.datetime.fromisoformat(base).replace(tzinfo=datetime.timezone.utc).timestamp())*10**9+int(frac.ljust(9,'0'))
def write(name,obj):(OUT/name).write_text(json.dumps(obj,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def main():
 report=json.loads((RUN/'report.json').read_text());plan=json.loads((ROOT/'prepared_plan.json').read_text());audit=json.loads((ROOT/'data/historical_data_audit.json').read_text())
 if len(report['rows'])!=60 or report['stop_reason'] is not None or not report['certified_complete']:raise ValueError('complete accepted-shaped run required')
 by={(r['instance_id'],r['capacity'],r['method']):r for r in report['rows']};pairs=[]
 for r in report['rows']:
  if r['method']=='FF':
   bf=by[(r['instance_id'],r['capacity'],'BF')];delta=r['used_bins']-bf['used_bins']
   pairs.append({'instance_id':r['instance_id'],'n':r['n'],'capacity':r['capacity'],'FF_bins':r['used_bins'],'BF_bins':bf['used_bins'],'FF_minus_BF':delta,'outcome':'BF_win' if delta>0 else 'FF_win' if delta<0 else 'tie'})
 observations=[json.loads((RUN/r['observation']).read_text()) for r in report['rows']]
 compact_rows=[{k:r[k] for k in ['index','id','instance_id','items_sha256','source_dtype','source_commit','n','capacity','method','phase','status','used_bins','L1','diagnostic_lower_bound','per_instance_excess','observation']} for r in report['rows']]
 summary={'study_id':'p3_eoh_2024_data_corrected_ff_bf_v1','title_zh':'P3：2024年作者仓库数据上的FF/BF更正重评分','preparation_freeze_sha256':sha(ROOT/'preparation_freeze.json'),'historical_numeric_sha256':sha(ROOT/'data/historical_numeric.json'),'report_sha256':sha(RUN/'report.json'),'source_commit':'e4b5ddba03b2b88025747e11c6049f8b529a4368','correction_and_baseline_definition_commit':'472545785c936dcfc863d2bc0d6109cf23c7ce62','first_blob_commit':'a27784a071fd86bd3de14fe60cea00b38bce3b0a','first_blob_date':'2024-05-14T05:37:15Z','started_utc':(ROOT/'results/launch_ff_bf_2024_data_batch_20261004_01/start_utc.txt').read_text().strip(),'ended_utc':(ROOT/'results/launch_ff_bf_2024_data_batch_20261004_01/end_utc.txt').read_text().strip(),'verification':{'status':'independently_reconciled','scope':'Saved320000assignments,60workerobservations,120events,60rows,12groups,resourcecosts and unchangedfreeze; no solver replay'},'counts':{'slots':60,'completed_valid':60,'failed':0,'unattempted':0,'distinct_item_sequences':15,'paired_sequence_capacity_comparisons':30,'item_assignment_records':sum(r['n'] for r in report['rows']),'distinct_worker_pids':len({o['pid'] for o in observations}),'api_model_gpu_calls':0},'pair_outcomes':dict(collections.Counter(p['outcome'] for p in pairs)),'groups':report['groups'],'rows':compact_rows,'cost':{'worker_cpu_seconds':report['cost']['worker_cpu_seconds'],'whole_supervisor_cpu_seconds':report['whole_cost']['supervisor_cpu_seconds'],'measured_through_initial_publication':report['measured_through_initial_publication'],'whole_wall_seconds':report['whole_cost']['wall_seconds'],'external_shell_start_to_end_seconds':(timestamp_ns((ROOT/'results/launch_ff_bf_2024_data_batch_20261004_01/end_utc.txt').read_text().strip())-timestamp_ns((ROOT/'results/launch_ff_bf_2024_data_batch_20261004_01/start_utc.txt').read_text().strip()))/10**9,'calibration_first20_worker_cpu_seconds':sum(r['execution']['worker_cpu_seconds'] for r in report['rows'][:20]),'remaining40_worker_cpu_seconds':sum(r['execution']['worker_cpu_seconds'] for r in report['rows'][20:]),'max_worker_cpu_seconds':max(o['worker_cpu_seconds'] for o in observations),'peak_worker_rss_kib':max(o['worker_peak_rss_kib'] for o in observations),'peak_supervisor_rss_kib':report['cost']['supervisor_peak_rss_kib'],'cleanup_seconds_total':sum(o['cleanup_seconds'] for o in observations),'cpu_evidence_complete':report['cost']['worker_cpu_evidence_complete'],'overhead_note':report['accounting_note'],'project_cost_note':'Official-data retrieval, preparation, earlier unit tests and independent verification are not included as a complete project-wide cost. Cloud monetary cost unavailable.'},'runtime':json.loads((ROOT/'protocol.json').read_text())['runtime'],'limits':json.loads((ROOT/'protocol.json').read_text())['budgets'],'evidence':{'full_report':'results/ff_bf_2024_data_batch_20261004_01/report.json','initial_ledger':'results/ff_bf_2024_data_batch_20261004_01/ledger_initial.json','events':'results/ff_bf_2024_data_batch_20261004_01/events.jsonl','observations':'results/ff_bf_2024_data_batch_20261004_01/observations/','historical_audit':'data/historical_data_audit.json','protocol':'protocol.json','pairs':'delivery/paired_results.json'},'limitations':['Author ICML2024-era repository identity, not proof of the exact bytes used by a particular paper table run','Current2026 official test values were replaced; current data were only compared, not scored in this batch','Historical data plus corrected all-instance capacities and current official FF/BF score definitions, executed as handwritten exact integer/tie equivalents','All feasible preallocated bins include unused bins and reveal total item count','Same15sequences are reused across2methods and2capacities; these are not60independent observations','L1 is a volume lower bound, not exact optimum; primary ratio-of-means differs from mean per-instance excess','Public reproduction evidence, not new blind generalization or LLM gain evidence','No published EoH program or evolutionary search executed; full P3 reproduction remains incomplete','Resource limits are per-process kernel caps plus observed/reserved aggregate budgets; no hard256MiB totalRSS claim']}
 write('summary.json',summary);write('paired_results.json',pairs)
 freeze=json.loads((ROOT/'preparation_freeze.json').read_text());write('source_hashes.json',{'freeze_sha256':sha(ROOT/'preparation_freeze.json'),'files':freeze['files'],'runtime_dependency_hashes':freeze['dependencies'],'python_executable_sha256':freeze['python_executable_sha256']})
 print(json.dumps({'summary_bytes':(OUT/'summary.json').stat().st_size,'paired_comparisons':len(pairs),'pair_outcomes':summary['pair_outcomes']},indent=2))
